package com.example.starter.gas.dto;

import jakarta.validation.constraints.DecimalMin;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;

import java.math.BigDecimal;
import java.time.Instant;

/**
 * 计量读数提交请求。
 *
 * @param requestId    幂等键
 * @param stationCode  交接站编码
 * @param meterTime    表底时刻（UTC），区间读数截止时刻
 * @param volume       本区间交接体积（体积单位，>0）
 * @param heatingValue 本区间热值（能量单位/体积单位，>0）
 */
public record ReadingSubmitRequest(
        @NotBlank String requestId,
        @NotBlank String stationCode,
        @NotNull Instant meterTime,
        @NotNull @DecimalMin(value = "0", inclusive = false) BigDecimal volume,
        @NotNull @DecimalMin(value = "0", inclusive = false) BigDecimal heatingValue) {
}

package com.example.starter.gas.dto;

import java.math.BigDecimal;
import java.time.Instant;
import java.time.LocalDate;

/**
 * 计量读数提交响应。
 *
 * @param duplicated 是否命中“同站同表底时刻”去重：true 表示读数已存在，本次未新写入
 */
public record ReadingSubmitResponse(
        String requestId,
        Long readingId,
        String stationCode,
        Instant meterTime,
        LocalDate gasDate,
        BigDecimal volume,
        BigDecimal heatingValue,
        boolean duplicated) {
}

package com.example.starter.gas.dto;

import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;

import java.time.LocalDate;

/**
 * 交接凭证生成请求：以气量日 24:00（UTC）前已确认入库的读数为准。
 */
public record VoucherCreateRequest(
        @NotBlank String requestId,
        @NotBlank String stationCode,
        @NotNull LocalDate gasDate) {
}

package com.example.starter.gas.dto;

import java.math.BigDecimal;
import java.time.Instant;
import java.time.LocalDate;

/**
 * 交接凭证视图。
 */
public record VoucherResponse(
        String voucherNo,
        String requestId,
        String voucherType,
        String originalVoucherNo,
        String stationCode,
        LocalDate gasDate,
        BigDecimal volume,
        BigDecimal weightedHeatingValue,
        BigDecimal energy,
        String status,
        String firstConfirmParty,
        LocalDate effectiveDate,
        Instant effectiveAt,
        Instant sealedAt) {
}

package com.example.starter.gas.dto;

import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.Pattern;

/**
 * 凭证确认请求：交接方 A 或 B 各自确认。
 */
public record ConfirmRequest(
        @NotBlank String requestId,
        @NotBlank @Pattern(regexp = "A|B") String party) {
}

package com.example.starter.gas.dto;

import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.Pattern;
import jakarta.validation.constraints.Size;

/**
 * 争议发起请求。
 */
public record DisputeRequest(
        @NotBlank String requestId,
        @NotBlank @Pattern(regexp = "A|B") String party,
        @NotBlank @Size(max = 500) String reason) {
}

package com.example.starter.gas.dto;

import jakarta.validation.constraints.NotBlank;

/**
 * 封账请求：争议期结束后封账为终态；重复封账幂等成功。
 */
public record SealRequest(@NotBlank String requestId) {
}

package com.example.starter.gas.dto;

import jakarta.validation.constraints.DecimalMin;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;

import java.math.BigDecimal;

/**
 * 调整凭证请求：封账后差错经双方签认（signOffA/signOffB 均为 true）处理，
 * 调整凭证引用原凭证号，提交即按双方签认生效。
 *
 * @param volume          修正后的交接体积合计（体积单位）
 * @param heatingValue    修正后的加权平均热值（能量单位/体积单位）
 * @param signOffA        A 方签认标记
 * @param signOffB        B 方签认标记
 */
public record AdjustmentRequest(
        @NotBlank String requestId,
        @NotNull @DecimalMin(value = "0", inclusive = false) BigDecimal volume,
        @NotNull @DecimalMin(value = "0", inclusive = false) BigDecimal heatingValue,
        @NotNull Boolean signOffA,
        @NotNull Boolean signOffB) {
}

package com.example.starter.gas.dto;

import java.math.BigDecimal;
import java.time.LocalDate;

/**
 * 日偏差考核明细视图：可逐日复算，结果稳定。
 */
public record AssessmentResponse(
        String stationCode,
        LocalDate gasDate,
        String voucherNo,
        BigDecimal nominatedEnergy,
        BigDecimal actualEnergy,
        BigDecimal deviation,
        BigDecimal deviationAbs,
        BigDecimal toleranceEnergy,
        boolean exempt,
        BigDecimal penalty) {
}

