                "SELECT * FROM meter_reading WHERE station_code = ? AND meter_time >= ? AND meter_time < ? "
                        + "AND created_at > ? ORDER BY meter_time ASC, id ASC",
                ROW_MAPPER, stationCode, dayStart, dayEnd, dayEnd);
    }
}

